// 统一改变i~j下标位置的数字
int clearNumbersBetweenIJ(int N, int i, int j) {
	for(int k = i; k <= j; k++) {
		if(N & (1 << k)) {	// 如果第 k 位是 1
			N -= (1 << k);	// 改为0
		}
		// 或者将i~j全部改为1
		for(int k = i; k <= j; k++) {
			mask |= (1 << k);  // 改为1
		}
	}
	return N;
}
