```cpp
string convertBase(string& input, int fromBase, int toBase){
	string result;
	const char* alpha = "0123456789abcdefghijklmnopqrstuvwxyz";
	int num = 0;
	// convert to 10 base
	for(char& c : input){
		int value = isdigit(c) ? c - '0' : tolower(c) - 'a' + 10;
		num = num * fromBase + value;
	}
	// convert to toBase
	while(num > 0){
		result.push_back(alpha[num % toBase]);
		num /= toBase;
	}
	reverse(result.begin(), result.end());
	return result;
}
