Miller-Rabin 概率性测试（推荐用于大数）
```cpp
bool isPrimeMillerRabin(int n, int k = 5) {
    if (n <= 1 || n == 4) return false;
    if (n <= 3) return true;
    int d = n - 1;
    while (d % 2 == 0)
        d /= 2;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(2, n - 2);
    for (int i = 0; i < k; i++) {
        int a = dis(gen);
        int x = pow(a, d) % n;
        if (x == 1 || x == n - 1)
            continue;
        bool composite = true;
        for (int r = 1; r < d; r *= 2) {
            x = (x * x) % n;
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite) return false;
    }
    return true;
}
```
