vector<int> sieve_of_eratosthenes(int n){
    // 创建一个布尔向量，初始化所有元素为 true
    vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false; // 0 和 1 不是素数
    // 只需要检查到 sqrt(n)
    // ------------核心代码--------------
    int sqrt_n = sqrt(n);
    for(int i = 2; i <= sqrt_n; ++i){
        if(is_prime[i]){
            // 将 i 的倍数标记为 false
            for(int j = i * i; j <= n; j += i){
                is_prime[j] = false;
            }
        }
    }
    // ------------核心代码--------------
    // 将所有素数存储到 vector<int> 中，不需要存储容器可以跳过
    vector<int> primes;
    for(int i = 2; i <= n; ++i){
        if(is_prime[i]){
            primes.push_back(i);
            /*
                将这里改成 count ++;可以直接计算结果
            */
        }
    }
    return primes;
}
```
