#### 欧拉筛法（线性筛法）
```cpp
vector<int> eulerSieveFast(int b) {
    if (b < 2) return {};

    vector<char> isPrime(b + 1, 1);
    vector<int> primes;
    isPrime[0] = isPrime[1] = 0;

    primes.reserve(b / log(b));  // 预分配空间，减少rehash

    // 单独处理2
    if (b >= 2) primes.push_back(2);

    // 只处理奇数
    for (int i = 3; i <= b; i += 2) {
        if (isPrime[i]) {
            primes.push_back(i);
        }

        int limit = b / i;
        // 内层循环从1开始（跳过2）
        for (int j = 1; j < primes.size() && primes[j] <= limit; ++j) {
            isPrime[primes[j] * i] = 0;
            if (i % primes[j] == 0) break;
        }
    }

    return primes;
}

// 获取 [a, b] 区间素数的函数
vector<int> getPrimesInRange(int a, int b) {
    if (a < 2) a = 2;
    auto allPrimes = eulerSieveFast(b);
    auto it = lower_bound(allPrimes.begin(), allPrimes.end(), a);
    return vector<int>(it, allPrimes.end());
}
```
线性筛法时间复杂度为 `O(n)` 非常节省时间，所有范围内的素数结果存放在 pri 数组中
-   `pri` 是一个数组，用于存储素数。
-   `now` 是一个计数器，用于记录当前找到的素数的数量。
-   `vis` 是一个布尔数组，用于标记每个数是否为合数。
-   如果 `i` 未被标记为合数（即 `vis[i]` 为 `false`），则将其标记为素数，并将其添加到 `pri` 数组中。
-   内层循环遍历已经找到的素数 `pri[j]`，并标记其倍数为合数。具体来说，`pri[j] * i` 会被标记为合数。
-   如果 `i` 能被 `pri[j]` 整除，则跳出内层循环，因此时 `i` 不是素数。 由于一个数字如果是偶数那么必然不是素数，所以 pri 数组大小可以是 `N + 9 >> 1`**需要判断范围大小的一半**，这一点比较重要，可以大大减小范围，如果需要进一步缩小范围或者优化 pri 大小占用，可以参考[[#素数#质数定理|质数定理]]中误差范围 模板代码
```cpp
template<typename T>
vector<T> euler(T& a, T& b) {
    static_assert(is_integral<T>::value, "T must be an integral type, (unsigned)int long or long long.");
    vector<T> primes, result;
    if (b < 2) return primes;
    if (a < 2) a = 2;
    vector<bool> isPrime(b + 1, true);
    isPrime[0] = isPrime[1] = false;
    for (T i = 2; i <= b; i++) {
        if (isPrime[i]) {
            primes.push_back(i);
        }
        for (T j = 0; j < primes.size() && primes[j] * i <= b; j++) {
            isPrime[primes[j] * i] = false;
            if (i % primes[j] == 0) {
                break;
            }
        }
    }
    vector<T> result;
    for (T& x : primes ) {
	    if (a <= x && x <= b) {
	        result.push_back(x);
	    }
	}
    return result;
}
```
