在输入内容为字符串（很长）时，使用：
```cpp
string divide(string num1, string num2, int precision) {
    if (num2 == "0") return "NaN"; // 除数为0
    string result;
    string current;
    int n = num1.size();
    // 处理整数部分
    for (int i = 0; i < n; i++) {
        current += num1[i];
        int count = 0;
        // 模拟减法
        while (current.size() > num2.size() || (current.size() == num2.size() && current >= num2)) {
            string temp = current;
            for (int j = 0; j < num2.size(); j++) {
                temp[temp.size() - 1 - j] -= num2[num2.size() - 1 - j] - '0';
                if (temp[temp.size() - 1 - j] < '0') {
                    temp[temp.size() - 1 - j] += 10;
                    temp[temp.size() - 2 - j]--;
                }
            }
            // 去掉前导零
            temp.erase(0, temp.find_first_not_of('0'));
            current = temp.empty() ? "0" : temp;
            count++;
        }
        result.push_back(count + '0');
    }
    // 如果整数部分为0，添加0
    if (result.empty()) result = "0";
    // 添加小数点
    result.push_back('.');
    // 处理小数部分
    for (int i = 0; i < precision; i++) {
        current += '0'; // 每次补一个0
        int count = 0;
        // 模拟减法
        while (current.size() > num2.size() || (current.size() == num2.size() && current >= num2)) {
            string temp = current;
            for (int j = 0; j < num2.size(); j++) {
                temp[temp.size() - 1 - j] -= num2[num2.size() - 1 - j] - '0';
                if (temp[temp.size() - 1 - j] < '0') {
                    temp[temp.size() - 1 - j] += 10;
                    temp[temp.size() - 2 - j]--;
                }
            }
            // 去掉前导零
            temp.erase(0, temp.find_first_not_of('0'));
            current = temp.empty() ? "0" : temp;
            count++;
        }
        result.push_back(count + '0');
    }
    // 去掉末尾多余的0
    result.erase(result.find_last_not_of('0') + 1, string::npos);
    if (result.back() == '.') result.pop_back(); // 如果小数部分全为0，去掉小数点
    return result;
}
```
### 取余
如果样本数字需要取余，并且范围有可能<0，需要使用 `(sum % k + k) % k` 纠正，这样得到的 modulus 余数永远是 `0~k-1` 的数字，记住即可
### 计算表达式
表达式为数字+符号（`+-*/()`），数字和结果都不超过 int
```cpp
class Evaluator {
private:
    string s;
    int pos;

    int parseNum() {
        int num = 0;
        while (pos < s.size() && isdigit(s[pos])) {
            num = num * 10 + (s[pos++] - '0');
        }
        return num;
    }

    int parseFactor() {
        if (s[pos] == '(') {
            pos++;
            int res = parseExpr();
            pos++; // skip ')'
            return res;
        }
        return parseNum();
    }

    int parseTerm() {
        int res = parseFactor();
        while (pos < s.size() && (s[pos] == '*' || s[pos] == '/')) {
            char op = s[pos++];
            int right = parseFactor();
            res = (op == '*') ? res * right : res / right;
        }
        return res;
    }

    int parseExpr() {
        int res = parseTerm();
        while (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) {
            char op = s[pos++];
            int right = parseTerm();
            res = (op == '+') ? res + right : res - right;
        }
        return res;
    }

public:
    int evaluate(const string& expr) {
        s = expr;
        pos = 0;
        return parseExpr();
    }
};
```
