```cpp
enum class State { OFF, ON };
string toggleState() {
    static State state = State::OFF; // 初始状态为 OFF
    const map<State, string> stateMap = {
        {State::OFF, "OFF"},
        {State::ON, "ON"}
    };
    // 切换状态
    state = (state == State::OFF) ? State::ON : State::OFF;
    cout << "State is " << stateMap.at(state) << endl;
    return stateMap.at(state);
}
```
