### 日期类型转换
#### 两个日期之间的所有日期
```cpp
vector<string> getDatesBetween(string start, string end) {
    vector<string> res;
    auto parse = [](string s) -> tuple<int, int, int> {
        return {stoi(s.substr(0,4)), stoi(s.substr(4,2)), stoi(s.substr(6,2))};
    };
    auto [y1, m1, d1] = parse(start);
    auto [y2, m2, d2] = parse(end);
    auto is_valid = [](int y, int m, int d) {
        if (m < 1 || m > 12 || d < 1) return false;
        int days[] = {31,28,31,30,31,30,31,31,30,31,30,31};
        if ((y%4 == 0 && y%100 != 0) || y%400 == 0) days[1]++;
        return d <= days[m-1];
    };
    if (!is_valid(y1, m1, d1) || !is_valid(y2, m2, d2)) return res;
    auto date_cmp = [](int y1, int m1, int d1, int y2, int m2, int d2) {
        return tie(y1, m1, d1) > tie(y2, m2, d2);
    };
    if (date_cmp(y1, m1, d1, y2, m2, d2)) swap(y1, y2), swap(m1, m2), swap(d1, d2);
    auto next_day = [](int& y, int& m, int& d) {
        int days[] = {31,28,31,30,31,30,31,31,30,31,30,31};
        if ((y%4 == 0 && y%100 != 0) || y%400 == 0) days[1]++;
        if (++d > days[m-1]) d = 1, m++;
        if (m > 12) m = 1, y++;
    };
    while (true) {
        stringstream ss;
        ss << setfill('0') << setw(4) << y1 << setw(2) << m1 << setw(2) << d1;
        res.push_back(ss.str());
        if (y1 == y2 && m1 == m2 && d1 == d2) break;
        next_day(y1, m1, d1);
    }
    return res;
}
```
上面的方法过于冗长，也不利于记忆
```cpp
vector<string> getDatesBetween(string start, string end) {
    vector<string> res;
    auto parse = [](string s) -> tm {
        tm t = {};
        t.tm_year = stoi(s.substr(0, 4)) - 1900; // tm_year 是从 1900 开始的年份
        t.tm_mon = stoi(s.substr(4, 2)) - 1;     // tm_mon 是 0-11
        t.tm_mday = stoi(s.substr(6, 2));        // tm_mday 是 1-31
        return t;
    };
    tm t1 = parse(start);
    tm t2 = parse(end);
    // 将 tm 转换为 time_t，确保日期合法
    time_t time1 = mktime(&t1);
    time_t time2 = mktime(&t2);
    if (time1 == -1 || time2 == -1) return res; // 如果日期非法，返回空结果
    while (time1 <= time2) {
        stringstream ss;
        ss << put_time(&t1, "%Y%m%d"); // 格式化日期为 YYYYMMDD
        res.push_back(ss.str());
        t1.tm_mday++;
        time1 = mktime(&t1); // 重新计算 time_t
    }
    return res;
}
```
