#### 判断日期是否合法
判断一个日期是否合法（是否真实存在这一天）：
```cpp
bool isValidDate(const string& date) {
    // 这里日期用字符串表示，格式符合 yyyy--mm--dd，如果不是这样的格式需要更改
    // ============================
    if (date.length() != 10 || date[4] != '-' || date[7] != '-') {
        return false;
    }
    int year = stoi(date.substr(0, 4));
    int month = stoi(date.substr(5, 2));
    int day = stoi(date.substr(8, 2));
    // =============================
    tm tm = {0, 0, 0, day, month - 1, year - 1900}; // tm_mon（0-11），tm_year（从1900年开始）
    time_t timestamp = mktime(&tm);
    if (timestamp == -1) { // 无法转换，即负数，超过合法的日期范围日期
        return false;
    }
    // 如果调整后的日期与输入日期不一致，说明原始日期非法
    if (tm.tm_mday != day || tm.tm_mon + 1 != month || tm.tm_year + 1900 != year) {
        return false;
    }
    return true;
}
```
