##### 使用正则表达式划分子串
```cpp
class Regular {
public:
    Regular(const string& input) {
        re_numbers = regex("\\d+");
        re_characters = regex("[A-Za-z]+");
        this->input = input;
    }
    void classify() {
        smatch match;
        string str = input; // 使用成员变量 input
        while (true) {
            if (regex_search(str, match, re_characters)) {
                characters.push_back(match.str());
                str = match.suffix().str();
            } else if (regex_search(str, match, re_numbers)) {
                numbers.push_back(stoi(match.str()));
                str = match.suffix().str();
            }
            // else if (/* other conditions */){
            //     /* code */
            // }
            if (match.empty()) {
                break;
            }
        }
    }
    void show_results() {
        for (auto x : numbers) {
            cout << x << "\t";
        }
        cout << endl;
        for (auto y : characters) {
            cout << y << "\t";
        }
    }
    void one_click() {
        classify();
        show_results();
    }
private:
    regex re_numbers;
    regex re_characters;
    vector<int> numbers;
    vector<string> characters;
    string input;
};
int main() {
    string str = "abc123def45";
    Regular obj(str);
    obj.one_click();
    return 0;
}
```
-   正则表达式中 smatch 只会存储一次检索结果，所以需要放在循环中，并且每循环一次使用 `match.suffix().str()` 更新被检测的字符串
-   `match.suffix()` 返回 match 中匹配到的字符串的位置后的字符串，再通过 `.str()` 得到更新
-   用构造函数初始化，`one_click()` 函数用于直接得到结果
