```cpp
using namespace std;
vector<int> init(string input =""){
    cin >> input;
    int gcount = 0, pcount = 0, lcount = 0, tcount = 0;
    for (int i = 0; i < input.length();i++){
        input[i] = tolower(input[i]);
        switch (input[i]){
        case 'g':	gcount++;	break;
        case 'p':   pcount++;   break;
        case 'l':   lcount++;   break;
        case 't':   tcount++;   break;
        default:    input.erase(input.begin() + i);		i--;	break;
        }
    }
    return {gcount, pcount, lcount, tcount};
}
void show_results(vector<int> counts){
    counts = init();
    while (counts[0] > 0 || counts[1] > 0 || counts[2] > 0 || counts[3] > 0) {
    for (int i = 0; i < 4; i++) {
        if (counts[i] > 0) {
            if (i == 0) cout << 'G';
            else if (i == 1) cout << 'P';
            else if (i == 2) cout << 'L';
            else if (i == 3) cout << 'T';
            counts[i]--;
            }
        }
    }
}
int main(){
    vector<int> vec(4, 0);
    show_results(vec);
}
```
#### 读取用特殊字符分开的字符串
`cin.get()`、`cin` `cin.getline()` 和 `getline()` 都是用于从输入流中读取数据的函数，但它们的行为和用途有所不同
-   `cin.get()` 是 `istream` 类的一个成员函数，用于读取单个字符或一行字符。
    -   适用于读取单个一行字符，直到某个设定位置停止
