#### 正则表达式暴力
也算是字符串匹配的一种，但就是暴力，不算是取巧的算法，一般情况下时间和空间复杂度都是 `O(n+m)` 但表达式比较复杂是，会花费大量时间构建 FSM [[刷题路线#8. 字符串转换整数 (atoi)]] [[刷题路线#151. 反转字符串中单词]] 对于较为复杂的字符串**提取和处理**，正则是最容易的解法
#### 基础知识
-   **负权环**（Negative Weight Cycle）是指在图中存在一个环路，使得这个环路中所有边的权值之和为负数。
-   **松弛操作**是指通过当前已知的路径信息，*尝试*找到一条更短的路径。具体来说，它的作用是更新从源点到某个顶点的最短路径。 负权环的效果
1.  **最短路径问题无解**
    -   如果从源点到某个点的路径上包含负权环，那么可以通过**无限次绕行这个环**，使得路径的总权值无限减小。
    -   因此，最短路径在这种情况下不存在。
2.  **算法失效**
    -   许多最短路径算法（如 Dijkstra、Bellman-Ford）在负权环存在时可能无法正确工作，或者会检测到负权环并报错。


算法比较：
| 算法  | 适用场景 | 时间复杂度 | 特点  |
| --- | --- | --- | --- |
| Dijkstra | 稀疏图、密集图 | `O((V + E) log V)` | 无法处理负权边，因此也无法检测负权环。 |
| Bellman-Ford | 稀疏图、带负权边 | `O(V * E)` | 可以检测负权环 |
| SPFA | 稀疏图、带负权边 | 平均 `O(E)` | Bellman-Ford 的优化 |
| Floyd-Warshall | 密集图、所有顶点对的最短路径 | `O(V^3)` | 计算所有顶点对的最短路径 |
### 最短路径算法
#### dijkstra 算法
基本算法：
```cpp
typedef pair<int, int> pii;
class Graph {
public:
    int V; // vertex number
    vector<vector<pii>> adjacent;// adjacent table,index for startpoint,then weight and endpoint
    Graph(int v) : V(v), adjacent(v)/*initialize the size of table*/ {}
    void addEdge(int u, int v, int weight) {
        adjacent[u].emplace_back(weight, v);
        // If undirected, uncomment the following line:
        adjacent[v].emplace_back(weight, u);
    }
};
vector<int> dijkstra(Graph& graph, int source /*the start point for begin*/) {
    int v = graph.V;
    vector<int> dist(v, numeric_limits<int>::max());//initialize the distance table
    dist[source] = 0;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    pq.emplace(0, source);
    while (!pq.empty()) {
        int current_dist = pq.top().first; // must get 0,node1 -> node1 is determined
        int u = pq.top().second; // must get source,the closet route is node1 -> node1
        pq.pop();
        if (current_dist > dist[u]) {
            continue;
        }
        for (auto& edge : graph.adjacent[u]) {
            int weight = edge.first;
            int v = edge.second;
            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                pq.emplace(dist[v], v);
            }
        }
    }
    return dist;
}
```
-   需要注意，算法中路径起始点从 0 开始，节点编号从零开始 ![[Pasted image 20250214100305.png]]
-   `dijkstra` 方法接受一个 `Graph` 对象和一个源顶点 `source`，返回一个 `vector<int>`，表示从源顶点到所有其他顶点的最短距离。
-   首先定义图 `Graph` 类，顶点数 v，`adjacent` 用来存储邻接表，`addEdge` 函数用来更新、存储邻接表，对一条从 uv 两个顶点之间的路径标上方向和权值
-   用优先队列 `priority_queue<pii, vector<pii>, greater<pii>> pq;` 作为容器，每个元素下标表示节点序号，每个元素是一个 `(距离, 节点)`
-   首先在优先队列中添加 `(0,source)` 表示起始点到自身的距离是 0
-   使用优先队列保证队列使用 `top()` 返回的一定是**当前节点所连接的节点路径中权重最小的一条路径**，也就是现在遍历到的这一条路径的权重比邻接表中记录的值更大，不用更新，优先队列（小顶堆）的作用是 **始终选择当前距离最短的顶点进行处理**，这是 Dijkstra 算法的核心贪心策略。配合 `if (current_dist > dist[u])` 来将当前节点连接路径中权重大于最小权重的路径一一忽略
-   `for (auto& edge : graph. adjacent[u]) {` 用来读取邻接表中**当前节点的所有数据**，也就是当前节点与其他节点的的连接关系和连接权重，用 `if (dist[u] + weight < dist[v])`，`if (dist[u] + weight < dist[v])` 用于检查通过 `u` 到达 `v` 的路径是否比当前已知的路径更短，如果是，则更新 `dist[v]`。配合 for 循环，在遍历当前节点和其他节点关系的同时找到当前节点到**指定目标节点**的最短路径
#### BellmanFord 算法
```cpp
class Graph {
public:
    int V;
    vector<vector<pii>> adjacent; // weight, to_point
    Graph(int v) : V(v), adjacent(v) {}
    void addEdge(int u, int v, int weight) {
        adjacent[u].emplace_back(weight, v);
        // adjacent[v].emplace_back(weight, u); // 如果是无向图，打开此注释
    }
};
class Solution {
public:
    vector<int> bellmanFord(Graph& graph, int source) {
        int V = graph.V;
        vector<int> dist(V, numeric_limits<int>::max());
        dist[source] = 0;
        // 最多进行 V-1 轮松弛
        for (int i = 0; i < V - 1; ++i) {
            for (int u = 0; u < V; ++u) {
                for (auto& edge : graph.adjacent[u]) {
                    int weight = edge.first;
                    int v = edge.second;
                    if (dist[u] != numeric_limits<int>::max() && dist[u] + weight < dist[v]) {
                        dist[v] = dist[u] + weight; // 松弛操作
                    }
                }
            }
        }
        // 检测负权环
        for (int u = 0; u < V; ++u) {
            for (auto& edge : graph.adjacent[u]) {
                int weight = edge.first;
                int v = edge.second;
                if (dist[u] != numeric_limits<int>::max() && dist[u] + weight < dist[v]) {
                    cout << "Graph contains negative weight cycle!" << endl;
                    return {}; // 检测到负权环，返回空数组
                }
            }
        }
        return dist;
    }
};
```
-   Bellman-Ford 算法的松弛操作本身就是检测负权环的关键部分。
-   **算法的核心逻辑**是通过 `V-1` 轮松弛操作，逐步优化最短路径。如果在 `V-1` 轮后，仍存在可以优化的路径，说明图中存在负权环。
#### SPFA
```cpp
class Graph {
public:
    int V;
    vector<vector<pii>> adjacent; // weight, to_point
    Graph(int v) : V(v), adjacent(v) {}
    void addEdge(int u, int v, int weight) {
        adjacent[u].emplace_back(weight, v);
        // adjacent[v].emplace_back(weight, u); // 如果是无向图，打开此注释
    }
};
class Solution {
public:
    vector<int> spfa(Graph& graph, int source) {
        int V = graph.V;
        vector<int> dist(V, numeric_limits<int>::max());
        vector<bool> inQueue(V, false); // 顶点是否在队列中
        // vector<int> count(V, 0); // mark
        queue<int> q;
        dist[source] = 0;
        q.push(source);
        inQueue[source] = true;
        // count[source]++; //mark
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inQueue[u] = false;
            for (auto& edge : graph.adjacent[u]) {
                int weight = edge.first;
                int v = edge.second;
                if (dist[u] != numeric_limits<int>::max() && dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight; // 松弛操作
                    if (!inQueue[v]) {
                        q.push(v);
                        inQueue[v] = true;
                    	// count[v]++; // 记录 v 的入队次数  mark
                    	// if (count[v] > V - 1) {  		mark
                        // 	return {}; // 存在负权环  	mark
                    	// }  								mark
                    }
                }
            }
        }
        return dist;
    }
};
```
-   **松弛操作**：`dist[v] = dist[u] + weight`，表示通过 `u` 到 `v` 的路径比当前记录的最短路径更短。
-   **队列管理**：通过 `inQueue` 数组避免同一个顶点多次加入队列，提高效率。
-   **终止条件**：当队列为空时，所有可能的最短路径已被更新。
-   如果需要检测负权环，则打开所有 mark 注释，如果返回数组为空则存在


负权环的检测方法：
-   **顶点入队次数**：
    -   如果一个顶点被加入队列的次数超过 `V-1` 次（`V` 是顶点数量），则说明图中存在负权环。
-   **实现方式**：
    -   使用一个数组 `count` 记录每个顶点被加入队列的次数。
    -   如果 `count[v] > V-1`，进入队列次数过多，超过了所有的节点数-1，理论上一个节点最多和 V-1 个其他节点相连，超过这个数说明图中存在**负权环**
#### Floyd-Warshall
```cpp
class Graph {
public:
    int V;
    vector<vector<int>> dist; // 直接存储所有顶点对的最短路径
    Graph(int v) : V(v), dist(v, vector<int>(v, numeric_limits<int>::max())) {
        for (int i = 0; i < V; ++i) {
            dist[i][i] = 0; // 顶点到自身的距离为 0
        }
    }
    void addEdge(int u, int v, int weight) {
        dist[u][v] = min(dist[u][v], weight); // 可能有重边，取最小权值
        // dist[v][u] = min(dist[v][u], weight); // 如果是无向图，打开此注释
    }
};
class Solution {
public:
    void floydWarshall(Graph& graph) {
        int V = graph.V;
        for (int k = 0; k < V; ++k) {
            for (int i = 0; i < V; ++i) {
                for (int j = 0; j < V; ++j) {
                    if (graph.dist[i][k] != numeric_limits<int>::max() &&
                        graph.dist[k][j] != numeric_limits<int>::max()) {
                        graph.dist[i][j] = min(graph.dist[i][j], graph.dist[i][k] + graph.dist[k][j]);
                    }
                }
            }
        }
    }
};
```
最朴素的实现，通过动态规划原理：
-   `dist[i][j]` 表示从顶点 `i` 到顶点 `j` 的最短路径。
-   如果通过中间顶点 `k` 可以使路径更短，则更新 `dist[i][j]`： ![[Pasted image 20250219215718.png|状态转移方程]] 原理是让每一个节点在其他所有节点之间遍历，看是否能找到距离更小的节点，找到了就根据状态方程更新 dist 表
### DFS 图论
#### 基本知识
题目一般会给出连接关系：
-   邻接表
-   邻接矩阵
-   迷宫图 其中邻接表和邻接矩阵可以相互转换，迷宫图则需要使用 dfs 手动实现节点遍历，二维图中需要向四个方向发散遍历


DFS算法的核心在于递归调用
1.  如果图是一个二维表（非邻接矩阵和邻接表的类似迷宫的表）
    1.  设定一个`vector<pair<int, int>> path`记下路径，vissted记录二维表中节点是否访问过
    2.  首先在dfs函数中首先实现遍历图的递归终止条件，终止条件为dfs函数遍历到边界过着已经访问过的节点
    3.  如果未终止，则记录路径并标记当前节点已访问
    4.  如果到达终点则不在向下递归搜索直接退出并返回路径，未达终点则继续向周围四个方向递归
    5.  子递归过程中如果没有被中断（找到终点，遇到边界或者节点已访问的情况）通过回溯修改已经遍历的节点为false，并移除当前节点
2.  如果图是一个邻接表或者邻接矩阵 6. 算法中一般先将邻接矩阵转化为邻接表，设置visited数组记录节点是否访问过 7. 同样在dfs函数中先实现递归终止条件，通过循环不断递归递归搜索邻接表节点 8. 同样的如果在子递归过程中没有被终止，则通过回溯清楚visited中访问标记
3.  如果问题是遍历节点数量或统计连通分量，则不需要回溯


一般的做法是用 dfs 函数修改外部变量，**不返回值**，如果有返回值那么返回值应该被利用起来[[刷题路线#841. 钥匙和房间|参考题目]]，在主函数中调用 dfs 函数
```cpp
class Solution{
public:
	void dfs(&查询依据, &现在状态, 目标状态, &更新容器){ // 现在状态，容器和依据是动态的
		递归到一个新的节点，更改现在状态或者更新容器
		if(边界或者已访问过终止递归条件){
			一般return ；
			如果需要更新容器则在此处更新容器记录
		}
		if(找到路径、现在状态==目标状态){
			更新容器或者其他操作，如果找到目标状态会在这里返回，而不是下面的无功而返
		}
		else{ // 表明在这个子递归中没有超过边界，也没有找到目标——>继续递归
			-------------邻接表做法----------------
			for(auto neighbor : adjacent[current]){
				dfs(查询依据, neighbor, 目标状态, 更新容器);
			}
			-------------二维表做法----------------
			dfs(x + 1, y, targetX, targetY/*目标状态*/,更新容器);
			dfs(x - 1, y, targetX, targetY,更新容器);
			dfs(x, y + 1, targetX, targetY,更新容器);
			dfs(x, y - 1, targetX, targetY,更新容器);
		}
		// 执行到这说明**所有的**子递归都被终止，也没找到目标状态，子递归无功而返
		回溯操作，移除visited中访问标记或者**当前子递归的**路径记录
	}
}
```
#### 经典实现
简单遍历，性质应用：
```cpp
class Graph {
public:
    int V; // 顶点数量
    vector<vector<int>> adj; // 邻接表
    vector<bool> visited; // 标记顶点是否被访问过
    Graph(int v) : V(v), adj(v), visited(v, false) {}
    // 添加边（无向图）
    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u); // 无向图需双向添加
    }
    void dfs(int node) {
        visited[node] = true; // 标记当前节点为已访问
        // 对当前节点的邻接节点进行遍历
        for (int neighbor : adj[node]) {
            if (!visited[neighbor]) {
                dfs(neighbor); // 递归访问邻接节点
            }
        }
    }
    ////////////////以上是实现，下面是利用实现的功能////////////////
	int countComponents(int n) { // 统计连通分量数量
	    int count = 0;
	    for (int i = 0; i < n; ++i) {
	        if (!visited[i]) {
	            dfs(i);
	            count++;
	        }
	    }
	    return count;
	}
	bool isConnected(int start, int end) {
	    dfs(start);
	    return visited[end];
	}
};
```
-   适用于已知节点数量的情况，首先使用 addEdge 函数构建邻接表
-   `dfs` 函数用来实现 `countComponents` 统计连通分量（计算图中有几个连通网络）和判断两个节点是否相连 `isConnected` 寻找路径问题： [797\. 所有可能的路径](https://leetcode.cn/problems/all-paths-from-source-to-target/) ^htlxsp [[刷题路线#841. 钥匙和房间]]
