class Maze {
public:
    unordered_map<int, vector<int>> adj; // 邻接表
    unordered_set<int> visited; // 记录已访问的节点
    int dfs(int start, int end) {
        if (start == end) {
            return 1; // 到达终点，返回路径节点数量 1
        }
        visited.insert(start); // 标记当前节点为已访问
        int minNodes = INT_MAX;
        for (int neighbor : adj[start]) {
            if (visited.find(neighbor) == visited.end()) {
                int nodes = dfs(neighbor, end); // 递归搜索
                if (nodes != -1) {
                    minNodes = min(minNodes, nodes + 1);
                }
            }
        }
        visited.erase(start); // 回溯：取消当前节点的访问标记
        return minNodes == INT_MAX ? -1 : minNodes; // 如果未找到路径，返回 -1
    }
    int minPathNodes(int start, int end) {
        return dfs(start, end);
    }
};
```
