#### 判断图中是否有环
```cpp
class Graph {
public:
    int V; // 顶点数量
    vector<vector<int>> adj; // 邻接矩阵
    vector<bool> visited; // 访问标记
    vector<bool> recStack; // 当前路径标记
    Graph(int v) : V(v), adj(v, vector<int>(v, 0)), visited(v, false), recStack(v, false) {}
    // 添加边
    void addEdge(int u, int v) {
        adj[u][v] = 1;
        adj[v][u] = 1; // 对于无向图，需要双向添加
    }
    // 判断图中是否存在环
    bool isCyclicUtil(int node) {
        if (!visited[node]) {
            visited[node] = true; // 标记为已访问
            recStack[node] = true; // 标记为当前路径的一部分
            // 遍历邻接节点
            for (int neighbor = 0; neighbor < V; ++neighbor) {
                if (adj[node][neighbor]) {
                    if (!visited[neighbor] && isCyclicUtil(neighbor)) {
                        return true;
                    }
                    if (recStack[neighbor]) {
                        return true; // 发现环
                    }
                }
            }
        }
        recStack[node] = false; // 回溯：取消当前路径标记
        return false;
    }
    bool isCyclic() {
        for (int i = 0; i < V; ++i) {
            if (isCyclicUtil(i)) {
                return true; // 发现环
            }
        }
        return false; // 没有环
    }
};
```
